theme.css:
/* theme: Heartland Metal | A steely, industrial palette with copper accents and editorial bones — a weekend digest where markets bleed, energy surges, and politics sharpens to a point. */

.diary-page {
  --paper: #f5f1e8;
  --paper-alt: #e8e2d4;
  --ink: #1a1a1a;
  --ink-soft: #2f2b26;
  --accent: #8e4a1f;
  --muted: #5f594e;
  --accent-ink: #fdfaf5;
  --rule: #c9c0b0;
  --font-display: var(--ff-fraunces), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #141310;
    --paper-alt: #1e1c18;
    --ink: #f0eadc;
    --ink-soft: #d8d1c2;
    --accent: #e89a6a;
    --muted: #a89f8d;
    --accent-ink: #1a110a;
    --rule: #35312a;
  }
}

.diary-page .diary-hero {
  background: linear-gradient(135deg, var(--paper-alt) 0%, var(--paper) 100%);
  border-bottom: 2px solid var(--accent);
  position: relative;
}

.diary-page .diary-hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 40%, var(--ink) 40%, var(--ink) 60%, var(--accent) 60%, var(--accent) 100%);
}

.diary-page .diary-crumbs a {
  letter-spacing: 0.12em;
}

.diary-page .diary-kicker {
  color: var(--accent);
  font-weight: 700;
  letter-spacing: 0.22em;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.03em;
  position: relative;
  display: inline-block;
}

.diary-page .diary-title::after {
  content: "";
  position: absolute;
  bottom: -8px;
  left: 0;
  width: 5.5rem;
  height: 3px;
  background: var(--accent);
}

.diary-page .diary-summary {
  font-size: clamp(1.2rem, 2.1vw, 1.45rem);
  line-height: 1.6;
  margin-top: 2rem;
}

.diary-page .diary-theme-note {
  margin-top: 2rem;
  padding: 0.75rem 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 2px;
  font-weight: 700;
  padding: 0.15rem 0.7rem;
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-right: 0.75rem;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 2px solid var(--ink);
}

.diary-page .diary-toc-nav {
  gap: 1.5rem;
}

.diary-page .diary-toc-label {
  font-weight: 700;
  letter-spacing: 0.18em;
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  font-family: var(--font-ui);
  font-weight: 600;
  font-size: 0.85rem;
  letter-spacing: 0.02em;
}

.diary-page .diary-toc-link {
  border-left: 2px solid transparent;
}

.diary-page .diary-toc-link:hover {
  border-left-color: var(--accent);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
  border-left-color: var(--accent);
}

.diary-page .diary-toc-number {
  font-family: var(--font-ui);
  font-weight: 600;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  color: var(--accent);
}

.diary-page .diary-section-head {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.05;
}

.diary-page .diary-section {
  position: relative;
}

.diary-page .diary-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--rule) 100%);
}

.diary-page .diary-section:first-child::before {
  display: none;
}

.diary-page .diary-prose {
  font-family: var(--font-body);
  font-size: 1.15rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 0.78rem;
  color: var(--ink);
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--rule);
  display: inline-block;
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-weight: 600;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
  font-family: var(--font-body);
}

.diary-page .diary-prose em {
  font-style: italic;
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
  color: var(--ink);
  font-style: italic;
  background: var(--paper-alt);
  padding: 0.75rem 1.25rem;
  margin-left: 0;
  margin-right: 0;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  height: 3px;
  width: 0.75rem;
}

.diary-page .diary-prose ol > li::marker {
  font-family: var(--font-ui);
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-left: 3px solid var(--accent);
}

.diary-page .diary-prose code {
  color: var(--accent);
  background: transparent;
}

.diary-page .diary-prose hr {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-footer {
  border-top: 2px solid var(--accent);
  background: var(--paper-alt);
  margin-top: 2rem;
  padding-block: 2.5rem 3rem;
}

.diary-page .diary-footer a {
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: color 150ms ease;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-footer-meta {
  font-size: 0.8rem;
  letter-spacing: 0.04em;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    position: sticky;
    top: 2rem;
    background: none;
    border: 0;
  }

  .diary-page .diary-toc-list {
    border-left: 2px solid var(--rule);
  }

  .diary-page .diary-toc-link {
    border-left: 2px solid transparent;
    margin-left: -2px;
    padding-left: 1rem;
  }

  .diary-page .diary-toc-link:hover {
    border-left-color: var(--accent);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page .diary-footer a {
    transition: none;
  }
}
